  KEY `Application_ID` (`Application_ID`),
  CONSTRAINT `payments_ibfk_1` FOREIGN KEY (`Application_ID`) REFERENCES `applications` (`Application_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
